import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture as textureNode } from 'three/tsl';

export default function createNode(config, ctx) {
  const ATLAS_RECT = { x: 0, y: 0, width: 512, height: 320 };
  const SCENE_HEIGHT = 1.0;

  // Calculate geometry dimensions based on atlas aspect ratio
  const aspectRatio = ATLAS_RECT.width / ATLAS_RECT.height;
  const sceneWidth = SCENE_HEIGHT * aspectRatio;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(sceneWidth, SCENE_HEIGHT);

  // Load texture via cached texture loader
  const texture = ctx.textureLoader.load(config.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Apply atlas UV offsets if texture is larger than source region
  if (texture.image) {
    const tw = texture.image.width;
    const th = texture.image.height;

    const minU = ATLAS_RECT.x / tw;
    const maxU = (ATLAS_RECT.x + ATLAS_RECT.width) / tw;
    const minV = ATLAS_RECT.y / th;
    const maxV = (ATLAS_RECT.y + ATLAS_RECT.height) / th;

    const uv = geometry.getAttribute('uv');
    const uvArray = uv.array;

    for (let i = 0; i < uvArray.length; i += 2) {
      uvArray[i] = minU + uvArray[i] * (maxU - minU);
      uvArray[i + 1] = minV + uvArray[i + 1] * (maxV - minV);
    }
    uv.needsUpdate = true;
  }

  // Create material with texture node
  const textureColorNode = textureNode(texture);
  const material = new MeshBasicNodeMaterial({
    colorNode: textureColorNode,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply transformation
  mesh.position.set(config.position[0], config.position[1], config.position[2]);
  mesh.rotation.set(config.rotation[0], config.rotation[1], config.rotation[2]);
  mesh.scale.set(config.scale[0], config.scale[1], config.scale[2]);

  // Setup resource cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  // Setup event handlers
  mesh.userData.handlers = {};

  return mesh;
}
